CREATE TABLE `graduate_applications` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `graduate_id` int(10) unsigned NOT NULL,
  `applied_by` int(10) unsigned NOT NULL,
  `application_date` date NOT NULL,
  `approved_at` date DEFAULT NULL,
  `approved_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_graduate_id` (`graduate_id`),
  KEY `applied_by` (`applied_by`),
  KEY `fk_graduate_applications_approved_by` (`approved_by`),
