  CONSTRAINT `graduate_applications_ibfk_1` FOREIGN KEY (`graduate_id`) REFERENCES `latin_honor_graduates` (`id`),
  CONSTRAINT `graduate_applications_ibfk_2` FOREIGN KEY (`applied_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5629 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
