--
-- Table structure for table `latin_honor_uploads`
--

DROP TABLE IF EXISTS `latin_honor_uploads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `latin_honor_uploads` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` int(10) unsigned NOT NULL,
  `school_year` varchar(9) NOT NULL,
  `original_filename` varchar(255) NOT NULL,
  `stored_filename` varchar(255) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `file_size` int(10) unsigned NOT NULL,
  `file_hash` char(64) NOT NULL,
  `uploaded_by` int(10) unsigned NOT NULL,
  `upload_number` int(10) unsigned NOT NULL DEFAULT 1,
  `extraction_status` enum('pending','extracted','reviewed','failed','draft') NOT NULL DEFAULT 'pending',
  `records_extracted` int(10) unsigned NOT NULL DEFAULT 0,
  `total_pages` int(10) unsigned DEFAULT NULL,
  `extracted_through_page` int(10) unsigned NOT NULL DEFAULT 0,
  `uploaded_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_school_year_uploadnum` (`school_id`,`school_year`,`upload_number`),
  KEY `uploaded_by` (`uploaded_by`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_file_hash` (`file_hash`),
  CONSTRAINT `latin_honor_uploads_ibfk_1` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`),
  CONSTRAINT `latin_honor_uploads_ibfk_2` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=243 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

